'use strict';

// Reproductions of each symptom in ISSUE.md (INC-5521). Races are driven by
// the store's latency: calls started together interleave at every store
// round trip, and the offset sweeps start the second call a few round trips
// after the first so it lands at each point of the first call's progress.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');
const { stockedService, ticks, seededRandom, assertLedger } = require('./helpers');

const OFFSETS = [0, 1, 2, 3, 4, 5, 6, 7, 8];

function outcomes(results) {
  return {
    fulfilled: results.filter(r => r.status === 'fulfilled'),
    rejected: results.filter(r => r.status === 'rejected')
  };
}

describe('INC-5521: oversold stock (263 orders confirmed on 250 units)', () => {
  test('concurrent reserves on a 250-unit drop hold exactly 250 units', async () => {
    const svc = await stockedService({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 300 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    const { fulfilled, rejected } = outcomes(results);
    assert.equal(fulfilled.length, 250);
    assert.equal(rejected.length, 50);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, `unexpected rejection: ${reason}`);
    }
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });
  });

  test('concurrent commits of every reservation sell exactly the stock on hand', async () => {
    const svc = await stockedService({ 'sneaker-limited': 250 });
    const orderIds = Array.from({ length: 263 }, (_, i) => `order-${i}`);
    const reserved = await Promise.allSettled(orderIds.map(id => svc.reserve(id, [{ sku: 'sneaker-limited', qty: 1 }])));
    const held = orderIds.filter((_, i) => reserved[i].status === 'fulfilled');
    assert.equal(held.length, 250);

    const committed = await Promise.all(held.map(id => svc.commit(id)));
    assert.ok(committed.every(r => r.status === 'committed'));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assert.rejects(svc.reserve('late', [{ sku: 'sneaker-limited', qty: 1 }]), InsufficientStockError);
  });

  test('multi-unit concurrent reserves never push available stock below zero', async () => {
    const svc = await stockedService({ widget: 10 });
    const results = await Promise.allSettled(
      Array.from({ length: 12 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 3 }]))
    );
    assert.equal(outcomes(results).fulfilled.length, 3);
    assert.equal(await svc.available('widget'), 1);
  });

  test('concurrent addStock calls during reserves lose no units', async () => {
    const svc = await stockedService({ widget: 5 });
    await Promise.all([
      ...Array.from({ length: 20 }, () => svc.addStock('widget', 1)),
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 25, reserved: 5, sold: 0 });
  });
});

describe('INC-5521: reserved went negative and did not recover', () => {
  test('expire leaves committed orders alone', async () => {
    let now = 0;
    const svc = await stockedService({ widget: 10 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('shipped', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('abandoned', [{ sku: 'widget', qty: 2 }]);
    await svc.commit('shipped');
    now = 5000;

    assert.deepEqual(await svc.expire(), ['abandoned']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
    assert.equal((await svc.commit('shipped')).status, 'committed');
  });

  test('release rejects a committed order and leaves the counters alone', async () => {
    const svc = await stockedService({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    await svc.commit('o1');

    await assert.rejects(svc.release('o1'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      return true;
    });
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 6, reserved: 0, sold: 4 });
  });

  test('releases of one order arriving at different moments return its units once', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
      await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
      const first = svc.release('o1');
      await ticks(offset);
      const results = await Promise.all([first, svc.release('o1')]);
      assert.ok(results.every(r => r.status === 'released'), `offset ${offset}`);
      assert.deepEqual(
        await svc.snapshot('widget'),
        { sku: 'widget', stock: 10, reserved: 0, sold: 0 },
        `double release at offset ${offset}`
      );
    }
  });

  test('expire racing a commit settles the order exactly once', async () => {
    for (const offset of OFFSETS) {
      for (const expireFirst of [true, false]) {
        let now = 0;
        const svc = await stockedService({ widget: 10 }, { now: () => now, reservationTtlMs: 1000 });
        await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
        now = 5000;

        const [a, b] = expireFirst ? [() => svc.expire(), () => svc.commit('o1')] : [() => svc.commit('o1'), () => svc.expire()];
        const first = a().then(value => ({ value }), error => ({ error }));
        await ticks(offset);
        const second = b().then(value => ({ value }), error => ({ error }));
        const [expired, committed] = expireFirst ? [await first, await second] : [await second, await first];
        const label = `offset ${offset}, ${expireFirst ? 'expire' : 'commit'} first`;

        const status = (await svc.getOrder('o1')).status;
        if (status === 'committed') {
          assert.deepEqual(expired.value, [], label);
          assert.equal(committed.value.status, 'committed', label);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 6, reserved: 0, sold: 4 }, label);
        } else {
          assert.equal(status, 'released', label);
          assert.deepEqual(expired.value, ['o1'], label);
          assert.ok(committed.error instanceof OrderStateError, label);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 }, label);
        }
      }
    }
  });
});

describe('INC-5521: a retried checkout held units twice', () => {
  test('a retry arriving at any point during the first reserve holds the units once', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
      const first = svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
      await ticks(offset);
      const [original, retry] = await Promise.all([first, svc.reserve('o1', [{ sku: 'widget', qty: 2 }])]);
      assert.deepEqual(retry, original, `offset ${offset}`);
      assert.equal(await svc.available('widget'), 8, `double hold at offset ${offset}`);

      await svc.release('o1');
      assert.equal(await svc.available('widget'), 10, `hold left after release at offset ${offset}`);
    }
  });

  test('a burst of concurrent retries returns one reservation and holds the units once', async () => {
    const svc = await stockedService({ widget: 10, gadget: 10 });
    const items = [{ sku: 'widget', qty: 2 }, { sku: 'gadget', qty: 1 }];
    const results = await Promise.all(Array.from({ length: 10 }, () => svc.reserve('o1', items)));
    for (const result of results) {
      assert.deepEqual(result, { orderId: 'o1', status: 'reserved', items });
    }
    assert.equal(await svc.available('widget'), 8);
    assert.equal(await svc.available('gadget'), 9);
  });

  test('a retry after the first attempt failed for stock tries again', async () => {
    const svc = await stockedService({ widget: 1 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 2 }]), InsufficientStockError);
    await svc.addStock('widget', 1);
    assert.equal((await svc.reserve('o1', [{ sku: 'widget', qty: 2 }])).status, 'reserved');
    assert.equal(await svc.available('widget'), 0);
  });
});

describe('INC-5521: a rejected bundle left its other item held', () => {
  test('a bundle with an out-of-stock item holds none of its items', async () => {
    const svc = await stockedService({ shoe: 5, lace: 1 });
    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }]),
      err => err instanceof InsufficientStockError && err.sku === 'lace' && err.available === 1
    );
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('lace'), 1);
    await assert.rejects(svc.release('bundle'), UnknownOrderError);
  });

  test('a bundle with an unknown sku holds none of its items', async () => {
    const svc = await stockedService({ shoe: 5 });
    await assert.rejects(svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'ghost', qty: 1 }]), UnknownSkuError);
    assert.equal(await svc.available('shoe'), 5);
  });

  test('bundles competing for the last units in opposite item order: one wins and the loser holds nothing', async () => {
    const svc = await stockedService({ shoe: 1, lace: 1 });
    const results = await Promise.allSettled([
      svc.reserve('b1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      svc.reserve('b2', [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }])
    ]);
    const { fulfilled, rejected } = outcomes(results);
    assert.equal(fulfilled.length, 1);
    assert.equal(rejected.length, 1);
    assert.ok(rejected[0].reason instanceof InsufficientStockError);

    const winner = fulfilled[0].value.orderId;
    await svc.release(winner);
    assert.equal(await svc.available('shoe'), 1, 'loser left a shoe held');
    assert.equal(await svc.available('lace'), 1, 'loser left a lace held');
  });

  test('a rejected bundle can be retried with the same orderId after a restock', async () => {
    const svc = await stockedService({ shoe: 5, lace: 0 === 0 ? 1 : 1 });
    const items = [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }];
    await assert.rejects(svc.reserve('bundle', items), InsufficientStockError);
    await svc.addStock('lace', 1);
    assert.equal((await svc.reserve('bundle', items)).status, 'reserved');
    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 5, reserved: 1, sold: 0 });
    assert.deepEqual(await svc.snapshot('lace'), { sku: 'lace', stock: 2, reserved: 2, sold: 0 });
  });
});

describe('INC-5521: sold counts exceeded shipped orders', () => {
  test('commits of one order arriving at different moments sell its units once', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
      await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
      const first = svc.commit('o1');
      await ticks(offset);
      const results = await Promise.all([first, svc.commit('o1')]);
      assert.ok(results.every(r => r.status === 'committed'), `offset ${offset}`);
      assert.deepEqual(
        await svc.snapshot('widget'),
        { sku: 'widget', stock: 7, reserved: 0, sold: 3 },
        `double commit at offset ${offset}`
      );
    }
  });

  test('commit racing release: exactly one wins and the counters match it', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
      await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
      const commit = svc.commit('o1').then(value => ({ value }), error => ({ error }));
      await ticks(offset);
      const release = svc.release('o1').then(value => ({ value }), error => ({ error }));
      const [c, r] = await Promise.all([commit, release]);
      const label = `offset ${offset}`;

      assert.equal([c, r].filter(x => x.error).length, 1, label);
      const loser = c.error || r.error;
      assert.ok(loser instanceof OrderStateError, label);
      const status = (await svc.getOrder('o1')).status;
      const expected = status === 'committed'
        ? { sku: 'widget', stock: 7, reserved: 0, sold: 3 }
        : { sku: 'widget', stock: 10, reserved: 0, sold: 0 };
      assert.deepEqual(await svc.snapshot('widget'), expected, label);
    }
  });
});

describe('INC-5521: flash sale replay', () => {
  test('40 workers with retries, double commits, releases and a mid-sale expire keep every counter consistent', async () => {
    const random = seededRandom(20260912);
    let now = 0;
    const svc = new InventoryService({ now: () => now, reservationTtlMs: 60_000 });
    const added = { 'sneaker-limited': 250, socks: 400 };
    for (const [sku, qty] of Object.entries(added)) {
      await svc.addStock(sku, qty);
    }

    const orders = Array.from({ length: 320 }, (_, i) => ({
      orderId: `sale-${i}`,
      items: random() < 0.3
        ? [{ sku: 'sneaker-limited', qty: 1 }, { sku: 'socks', qty: 2 }]
        : [{ sku: 'sneaker-limited', qty: 1 }],
      retry: random() < 0.25,
      action: random()
    }));
    let next = 0;
    let processed = 0;
    let expireRun;

    async function worker() {
      while (next < orders.length) {
        const order = orders[next++];
        const attempts = order.retry ? 2 : 1;
        const results = await Promise.allSettled(
          Array.from({ length: attempts }, () => svc.reserve(order.orderId, order.items))
        );
        processed += 1;
        if (processed === 120) {
          // The nightly job fires mid-sale, after every reservation so far has gone stale.
          now += 120_000;
          expireRun = svc.expire();
        }
        if (results[0].status === 'rejected') {
          assert.ok(results[0].reason instanceof InsufficientStockError, String(results[0].reason));
          continue;
        }
        const settle = order.action < 0.6
          ? [svc.commit(order.orderId), svc.commit(order.orderId)]
          : order.action < 0.85 ? [svc.release(order.orderId)] : [];
        for (const result of await Promise.allSettled(settle)) {
          if (result.status === 'rejected') {
            // Only expire can beat a worker to its order.
            assert.ok(result.reason instanceof OrderStateError, String(result.reason));
          }
        }
      }
    }

    await Promise.all(Array.from({ length: 40 }, worker));
    await expireRun;

    const statuses = await assertLedger(svc, added, orders.map(o => o.orderId));
    const sneakers = await svc.snapshot('sneaker-limited');
    assert.ok(sneakers.sold <= 250, `sold ${sneakers.sold} of 250 sneakers`);
    assert.equal(sneakers.sold + sneakers.stock, 250);
    assert.ok(statuses.committed > 0 && statuses.released > 0 && statuses.missing > 0, JSON.stringify(statuses));
  });
});

