'use strict';

// Reproductions of each symptom in ISSUE.md (INC-5521). Races are driven by
// the store's latency: calls started together interleave at every store
// round trip, and the offset sweeps start the second call a few round trips
// after the first so it lands at each point of the first call's progress.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');
const { stockedService, ticks, seededRandom, assertLedger } = require('./helpers');

const OFFSETS = [0, 1, 2, 3, 4, 5, 6, 7, 8];

function outcomes(results) {
  return {
    fulfilled: results.filter(r => r.status === 'fulfilled'),
    rejected: results.filter(r => r.status === 'rejected')
  };
}

describe('INC-5521: oversold stock (263 orders confirmed on 250 units)', () => {
  test('concurrent reserves on a 250-unit drop hold exactly 250 units', async () => {
    const svc = await stockedService({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 300 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    const { fulfilled, rejected } = outcomes(results);
    assert.equal(fulfilled.length, 250);
    assert.equal(rejected.length, 50);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, `unexpected rejection: ${reason}`);
    }
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });
  });

  test('concurrent commits of every reservation sell exactly the stock on hand', async () => {
    const svc = await stockedService({ 'sneaker-limited': 250 });
    const orderIds = Array.from({ length: 263 }, (_, i) => `order-${i}`);
    const reserved = await Promise.allSettled(orderIds.map(id => svc.reserve(id, [{ sku: 'sneaker-limited', qty: 1 }])));
    const held = orderIds.filter((_, i) => reserved[i].status === 'fulfilled');
    assert.equal(held.length, 250);

    const committed = await Promise.all(held.map(id => svc.commit(id)));
    assert.ok(committed.every(r => r.status === 'committed'));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assert.rejects(svc.reserve('late', [{ sku: 'sneaker-limited', qty: 1 }]), InsufficientStockError);
  });

  test('multi-unit concurrent reserves never push available stock below zero', async () => {
    const svc = await stockedService({ widget: 10 });
    const results = await Promise.allSettled(
      Array.from({ length: 12 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 3 }]))
    );
    assert.equal(outcomes(results).fulfilled.length, 3);
    assert.equal(await svc.available('widget'), 1);
  });

  test('concurrent addStock calls during reserves lose no units', async () => {
    const svc = await stockedService({ widget: 5 });
    await Promise.all([
      ...Array.from({ length: 20 }, () => svc.addStock('widget', 1)),
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 25, reserved: 5, sold: 0 });
  });
});

describe('INC-5521: reserved went negative and did not recover', () => {
  test('expire leaves committed orders alone', async () => {
    let now = 0;
    const svc = await stockedService({ widget: 10 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('shipped', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('abandoned', [{ sku: 'widget', qty: 2 }]);
    await svc.commit('shipped');
    now = 5000;

    assert.deepEqual(await svc.expire(), ['abandoned']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
    assert.equal((await svc.commit('shipped')).status, 'committed');
  });

  test('release rejects a committed order and leaves the counters alone', async () => {
    const svc = await stockedService({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    await svc.commit('o1');

    await assert.rejects(svc.release('o1'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      return true;
    });
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 6, reserved: 0, sold: 4 });
  });

  test('releases of one order arriving at different moments return its units once', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
      await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
      const first = svc.release('o1');
      await ticks(offset);
      const results = await Promise.all([first, svc.release('o1')]);
      assert.ok(results.every(r => r.status === 'released'), `offset ${offset}`);
      assert.deepEqual(
        await svc.snapshot('widget'),
        { sku: 'widget', stock: 10, reserved: 0, sold: 0 },
        `double release at offset ${offset}`
      );
    }
  });

  test('expire racing a commit settles the order exactly once', async () => {
    for (const offset of OFFSETS) {
      for (const expireFirst of [true, false]) {
        let now = 0;
        const svc = await stockedService({ widget: 10 }, { now: () => now, reservationTtlMs: 1000 });
        await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
        now = 5000;

        const [a, b] = expireFirst ? [() => svc.expire(), () => svc.commit('o1')] : [() => svc.commit('o1'), () => svc.expire()];
        const first = a().then(value => ({ value }), error => ({ error }));
        await ticks(offset);
        const second = b().then(value => ({ value }), error => ({ error }));
        const [expired, committed] = expireFirst ? [await first, await second] : [await second, await first];
        const label = `offset ${offset}, ${expireFirst ? 'expire' : 'commit'} first`;

        const status = (await svc.getOrder('o1')).status;
        if (status === 'committed') {
          assert.deepEqual(expired.value, [], label);
          assert.equal(committed.value.status, 'committed', label);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 6, reserved: 0, sold: 4 }, label);
        } else {
          assert.equal(status, 'released', label);
          assert.deepEqual(expired.value, ['o1'], label);
          assert.ok(committed.error instanceof OrderStateError, label);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 }, label);
        }
      }
    }
  });
});

describe('INC-5521: a retried checkout held units twice', () => {
  test('a retry arriving at any point during the first reserve holds the units once', async () => {
    for (const offset of OFFSETS) {
      const svc = await stockedService({ widget: 10 });
