  });

  test('a retry after the first attempt failed for stock tries again', async () => {
    const svc = await stockedService({ widget: 1 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 2 }]), InsufficientStockError);
    await svc.addStock('widget', 1);
