'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedMutex } = require('../src/keyed-mutex');
const { ticks, within } = require('./helpers');

describe('KeyedMutex', () => {
  test('callers of one key run one at a time in arrival order', async () => {
    const mutex = new KeyedMutex();
    const events = [];
    let inside = 0;
    await Promise.all([1, 2, 3].map(n => mutex.withLock('k', async () => {
      inside += 1;
      assert.equal(inside, 1, 'two holders of one key at once');
      events.push(`start ${n}`);
      await ticks(3);
      events.push(`end ${n}`);
      inside -= 1;
    })));
    assert.deepEqual(events, ['start 1', 'end 1', 'start 2', 'end 2', 'start 3', 'end 3']);
  });

  test('different keys run in parallel', async () => {
    const mutex = new KeyedMutex();
    let releaseA;
    const heldA = mutex.withLock('a', () => new Promise(resolve => { releaseA = resolve; }));
    await within(500, mutex.withLock('b', async () => 'done'), 'key b waited for key a');
    releaseA();
    await heldA;
  });

  test('returns what fn returns', async () => {
    const mutex = new KeyedMutex();
    assert.equal(await mutex.withLock('k', async () => 42), 42);
    assert.equal(await mutex.withLocks(['a', 'b'], () => 'sync value'), 'sync value');
  });

  test('releases the key and rethrows when fn throws', async () => {
    const mutex = new KeyedMutex();
    await assert.rejects(mutex.withLock('k', async () => { throw new Error('boom'); }), /boom/);
    await assert.rejects(mutex.withLock('k', () => { throw new Error('sync boom'); }), /sync boom/);
    assert.equal(await within(500, mutex.withLock('k', async () => 'free'), 'key stayed locked after a throw'), 'free');
    assert.equal(mutex.size, 0);
  });

  test('forgets a key once nobody holds or waits for it', async () => {
    const mutex = new KeyedMutex();
    const work = Array.from({ length: 50 }, (_, i) => mutex.withLocks([`k${i % 5}`, `k${(i + 1) % 5}`], () => ticks(1)));
    assert.ok(mutex.size > 0);
    await Promise.all(work);
    assert.equal(mutex.size, 0);
  });

  test('calling a release function twice does not let two waiters in', async () => {
    const mutex = new KeyedMutex();
    const release = await mutex.acquire('k');
    const order = [];
    const second = mutex.acquire('k').then(r => { order.push('second'); return r; });
    const third = mutex.acquire('k').then(r => { order.push('third'); return r; });
    release();
    release();
    await ticks(2);
    assert.deepEqual(order, ['second'], 'a double release handed the key to a second waiter');
    (await second)();
    (await third)();
    assert.equal(mutex.size, 0);
  });

  test('overlapping key sets taken in opposite order do not deadlock', async () => {
    const mutex = new KeyedMutex();
    const runs = Array.from({ length: 20 }, (_, i) => {
      const keys = i % 2 === 0 ? ['x', 'y', 'z'] : ['z', 'y', 'x'];
      return mutex.withLocks(keys, () => ticks(1));
    });
    await within(2000, Promise.all(runs), 'withLocks deadlocked');
    assert.equal(mutex.size, 0);
  });

  test('duplicate keys are taken once and an empty key list just runs fn', async () => {
    const mutex = new KeyedMutex();
    assert.equal(await within(500, mutex.withLocks(['k', 'k'], async () => 'ok'), 'duplicate key self-deadlocked'), 'ok');
    assert.equal(await mutex.withLocks([], async () => 'no keys'), 'no keys');
    assert.equal(mutex.size, 0);
  });

  test('unicode keys are distinct locks', async () => {
    const mutex = new KeyedMutex();
    let releaseFirst;
    const first = mutex.withLock('sku:café', () => new Promise(resolve => { releaseFirst = resolve; }));
    await within(500, mutex.withLock('sku:café', async () => 'other key'), 'distinct unicode keys shared a lock');
    releaseFirst();
    await first;
  });
});

