'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownOrderError,
  OrderStateError
} = require('../src');
const {
  within,
  settlesWithin,
  GatedStore,
  FlakyStore,
  SharedReferenceStore,
  seededRandom,
  assertLedger
} = require('./helpers');

const WAIT_LIMIT_MS = 1000;

async function serviceOn(store, stock, options = {}) {
  const svc = new InventoryService({ store, ...options });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

describe('calls that share no sku and no order do not wait for each other (INC-5490 regression)', () => {
  test('reserve, commit, release and addStock on another sku finish while a reserve is stalled in the store', async () => {
    const store = new GatedStore();
    const svc = await serviceOn(store, { a: 5, b: 5 });
    const gate = store.gate('sku:a');
    const stalled = svc.reserve('order-a', [{ sku: 'a', qty: 1 }]);
    await gate.arrived;

    await within(WAIT_LIMIT_MS, (async () => {
      await svc.reserve('order-b', [{ sku: 'b', qty: 2 }]);
      await svc.commit('order-b');
      await svc.reserve('order-b2', [{ sku: 'b', qty: 1 }]);
      await svc.release('order-b2');
      await svc.addStock('b', 3);
    })(), 'a call on sku b waited for a stalled call on sku a');
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 6, reserved: 0, sold: 2 });

    gate.open();
    assert.equal((await stalled).status, 'reserved');
    assert.equal(await svc.available('a'), 4);
  });

  test('checkout on other skus keeps going while expire is stalled releasing an order', async () => {
    let now = 0;
    const store = new GatedStore();
    const svc = await serviceOn(store, { a: 5, b: 5 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('old-a', [{ sku: 'a', qty: 2 }]);
    now = 5000;
    const gate = store.gate('sku:a');
    const sweep = svc.expire();
    await gate.arrived;

    await within(WAIT_LIMIT_MS, (async () => {
      await svc.reserve('fresh-b', [{ sku: 'b', qty: 1 }]);
      await svc.commit('fresh-b');
    })(), 'checkout on sku b waited for expire working on sku a');

    gate.open();
    assert.deepEqual(await sweep, ['old-a']);
    assert.equal(await svc.available('a'), 5);
  });

  test('expire finishes while a reserve on an unrelated sku is stalled', async () => {
    let now = 0;
    const store = new GatedStore();
    const svc = await serviceOn(store, { a: 5, b: 5 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('old-b', [{ sku: 'b', qty: 2 }]);
    now = 5000;
    const gate = store.gate('sku:a');
    const stalled = svc.reserve('order-a', [{ sku: 'a', qty: 1 }]);
    await gate.arrived;

    assert.deepEqual(await within(WAIT_LIMIT_MS, svc.expire(), 'expire waited for a reserve on another sku'), ['old-b']);
    gate.open();
    await stalled;
  });

  test('a second reserve on the same sku waits for the first', async () => {
    const store = new GatedStore();
    const svc = await serviceOn(store, { a: 5 });
    const gate = store.gate('sku:a');
    const first = svc.reserve('o1', [{ sku: 'a', qty: 1 }]);
    await gate.arrived;
    const second = svc.reserve('o2', [{ sku: 'a', qty: 1 }]);

    assert.equal(await settlesWithin(50, second), false, 'second reserve on sku a did not wait');
    gate.open();
    await Promise.all([first, second]);
    assert.equal(await svc.available('a'), 3);
  });

  test('two services sharing one store share locks and do not oversell', async () => {
    const store = new Store();
    const left = await serviceOn(store, { widget: 10 });
    const right = new InventoryService({ store });
    const results = await Promise.allSettled(
      Array.from({ length: 30 }, (_, i) => (i % 2 ? left : right).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
    assert.deepEqual(await left.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 10, sold: 0 });
  });
});

describe('store failures leave no partial writes and no stuck locks', () => {
  test('a failed write during reserve undoes the holds already written', async () => {
    const store = new FlakyStore();
    const svc = await serviceOn(store, { a: 5, b: 5 });
    const items = [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }];
    store.fail('set', 'sku:b', [1]);

    await assert.rejects(svc.reserve('o1', items), /store unavailable: set sku:b/);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 0, sold: 0 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 5, reserved: 0, sold: 0 });
    await assert.rejects(svc.getOrder('o1'), UnknownOrderError);

    const retry = await within(WAIT_LIMIT_MS, svc.reserve('o1', items), 'retry after a store failure hung');
    assert.equal(retry.status, 'reserved');
    assert.equal(await svc.available('a'), 3);
    assert.equal(await svc.available('b'), 4);
  });

  for (const { action, status, after } of [
    { action: 'commit', status: 'committed', after: { sku: 'a', stock: 3, reserved: 0, sold: 2 } },
    { action: 'release', status: 'released', after: { sku: 'a', stock: 5, reserved: 0, sold: 0 } }
  ]) {
    test(`a failed order write during ${action} undoes the counter changes and can be retried`, async () => {
      const store = new FlakyStore();
      const svc = await serviceOn(store, { a: 5 });
      await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
      store.fail('set', 'order:o1', [1]);

      await assert.rejects(svc[action]('o1'), /store unavailable: set order:o1/);
      assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 2, sold: 0 });
      assert.equal((await svc.getOrder('o1')).status, 'reserved');

      assert.equal((await svc[action]('o1')).status, status);
      assert.deepEqual(await svc.snapshot('a'), after);
    });
  }

  test('a failed write during expire leaves the order reserved for the next sweep', async () => {
    let now = 0;
    const store = new FlakyStore();
    const svc = await serviceOn(store, { a: 5 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    now = 5000;
    store.fail('set', 'sku:a', [1]);

    await assert.rejects(svc.expire(), /store unavailable: set sku:a/);
    assert.equal((await svc.getOrder('o1')).status, 'reserved');
    assert.deepEqual(await svc.expire(), ['o1']);
    assert.equal(await svc.available('a'), 5);
  });

  test('a failed rollback reports the original and the rollback errors together', async () => {
    const store = new FlakyStore();
    const svc = await serviceOn(store, { a: 5, b: 5 });
    store.fail('set', 'sku:b', [1]);
    store.fail('set', 'sku:a', [2]);

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]), err => {
      assert.ok(err instanceof AggregateError);
      assert.match(err.message, /sku:a/);
      assert.deepEqual(err.errors.map(e => e.message), ['store unavailable: set sku:b', 'store unavailable: set sku:a']);
      return true;
    });
  });

  test('a failed read releases the locks it held', async () => {
    const store = new FlakyStore();
    const svc = await serviceOn(store, { a: 5 });
    await svc.reserve('o1', [{ sku: 'a', qty: 1 }]);
    store.fail('get', 'sku:a', [1]);
    store.fail('get', 'order:o1', [1]);

    await assert.rejects(svc.reserve('o2', [{ sku: 'a', qty: 1 }]), /store unavailable: get sku:a/);
    await assert.rejects(svc.commit('o1'), /store unavailable: get order:o1/);
    await within(WAIT_LIMIT_MS, Promise.all([svc.reserve('o2', [{ sku: 'a', qty: 1 }]), svc.commit('o1')]), 'locks leaked after a failed read');
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 4, reserved: 1, sold: 1 });
  });
});

describe('stores and callers that share object references', () => {
  test('a rejected bundle leaves records in a non-cloning store untouched', async () => {
    const svc = await serviceOn(new SharedReferenceStore(), { shoe: 5, lace: 1 });
    await assert.rejects(svc.reserve('b1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }]), InsufficientStockError);
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('lace'), 1);
  });

  test('concurrent reserves on a non-cloning store do not oversell', async () => {
    const svc = await serviceOn(new SharedReferenceStore(), { widget: 10 });
    const results = await Promise.allSettled(
      Array.from({ length: 25 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
    assert.equal(await svc.available('widget'), 0);
  });

  test('changing a returned value does not change the stored record', async () => {
    const svc = new InventoryService({ store: new SharedReferenceStore() });
    const added = await svc.addStock('widget', 5);
    added.stock = 999;
    const reservation = await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    reservation.status = 'committed';
    reservation.items[0].qty = 99;
    const snap = await svc.snapshot('widget');
    snap.reserved = -1;

    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 5, reserved: 1, sold: 0 });
    assert.deepEqual(await svc.release('o1'), { orderId: 'o1', status: 'released', items: [{ sku: 'widget', qty: 1 }] });
  });

  test('reserve holds what the caller asked for even if the caller changes its array afterwards', async () => {
    const svc = new InventoryService();
    await svc.addStock('widget', 10);
    await svc.addStock('gadget', 10);
    const items = [{ sku: 'widget', qty: 2 }];
    const pending = svc.reserve('o1', items);
    items[0].qty = 9;
    items.push({ sku: 'gadget', qty: 1 });

    assert.deepEqual((await pending).items, [{ sku: 'widget', qty: 2 }]);
    assert.equal(await svc.available('widget'), 8);
    assert.equal(await svc.available('gadget'), 10);
  });

  test('reserve does not mutate the caller\'s items', async () => {
    const svc = new InventoryService();
    await svc.addStock('widget', 10);
    const items = Object.freeze([Object.freeze({ sku: 'widget', qty: 2 })]);
    assert.equal((await svc.reserve('o1', items)).status, 'reserved');
    assert.deepEqual(items, [{ sku: 'widget', qty: 2 }]);
  });
});

describe('randomized concurrent stress', () => {
  const SKUS = ['s0', 's1', 's2', 's3', 's4'];
  const EXPECTED = [InsufficientStockError, UnknownOrderError, OrderStateError];

  for (const seed of [1, 7, 42, 1337, 20260912]) {
    test(`random concurrent calls keep counters equal to the order ledger (seed ${seed})`, async () => {
      const random = seededRandom(seed);
      const pick = list => list[Math.floor(random() * list.length)];
      let now = 0;
      const svc = new InventoryService({ now: () => now, reservationTtlMs: 50 });
      const added = {};
      for (const sku of SKUS) {
        added[sku] = 15;
        await svc.addStock(sku, 15);
      }
      const orderIds = [];

      async function step() {
        const roll = random();
        // A small pool of ids makes retries and races on one order common.
        const orderId = `o${Math.floor(random() * 60)}`;
        if (roll < 0.4) {
          const skus = [...new Set([pick(SKUS), pick(SKUS), pick(SKUS)])];
          orderIds.push(orderId);
          await svc.reserve(orderId, skus.map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) })));
        } else if (roll < 0.6) {
          await svc.commit(orderId);
        } else if (roll < 0.75) {
          await svc.release(orderId);
        } else if (roll < 0.85) {
          const sku = pick(SKUS);
          const qty = 1 + Math.floor(random() * 4);
          added[sku] += qty;
          await svc.addStock(sku, qty);
        } else if (roll < 0.93) {
          now += 20;
          await svc.expire();
        } else {
          const sku = pick(SKUS);
          assert.ok((await svc.available(sku)) >= 0, `${sku} showed negative available stock`);
        }
      }

      async function worker() {
        for (let i = 0; i < 25; i++) {
          try {
            await step();
          } catch (error) {
            if (!EXPECTED.some(type => error instanceof type)) {
              throw error;
            }
          }
        }
      }

      await Promise.all(Array.from({ length: 40 }, worker));
      const statuses = await assertLedger(svc, added, orderIds);
      assert.ok(statuses.committed > 0 && statuses.released > 0, JSON.stringify(statuses));
    });
  }
});

